SET NOCOUNT ON;
DECLARE @Results TABLE(Test nvarchar(200));
IF EXISTS(SELECT 1 FROM UsersMembers WHERE Type=7 AND IsActive=1) OR NOT EXISTS(SELECT 1 FROM UsersMembers WHERE ID=7) THROW 51999,'Retirement failed',1;
INSERT @Results VALUES('Old external account disabled; history row retained');
BEGIN TRY UPDATE UsersMembers SET IsActive=1 WHERE ID=7;THROW 51999,'Reactivation allowed',1;END TRY BEGIN CATCH IF ERROR_NUMBER()<>51910 THROW;END CATCH;
INSERT @Results VALUES('External reactivation blocked');
DECLARE @Hash varbinary(32)=HASHBYTES('SHA2_256','password'),@Salt varbinary(32)=CRYPT_GEN_RANDOM(32),@Stamp uniqueidentifier,@Version binary(8);
BEGIN TRY EXEC Customer_SaveLogin @Actor=2,@AccountID=1,@Username='customer',@Hash=@Hash,@Salt=@Salt;THROW 51999,'Employee can create credentials',1;END TRY BEGIN CATCH IF ERROR_NUMBER()<>51910 THROW;END CATCH;
INSERT @Results VALUES('Only system administrator provisions credentials');
EXEC Customer_SaveLogin @Actor=1,@AccountID=1,@Username='customer',@Hash=@Hash,@Salt=@Salt;
EXEC Customer_SaveLogin @Actor=1,@AccountID=2,@Username='customer2',@Hash=@Hash,@Salt=@Salt;
BEGIN TRY EXEC Customer_SaveLogin @Actor=1,@AccountID=2,@Username=' CUSTOMER ',@Hash=@Hash,@Salt=@Salt;THROW 51999,'Duplicate username allowed',1;END TRY BEGIN CATCH IF ERROR_NUMBER()<>51910 THROW;END CATCH;
INSERT @Results VALUES('One customer login; normalized unique usernames');
SELECT @Stamp=SecurityStamp FROM Customer_Logins WHERE AccountID=1;
EXEC Customer_LoginResult 1,@Stamp,0;EXEC Customer_LoginResult 1,@Stamp,0;EXEC Customer_LoginResult 1,@Stamp,0;EXEC Customer_LoginResult 1,@Stamp,0;EXEC Customer_LoginResult 1,@Stamp,0;
IF NOT EXISTS(SELECT 1 FROM Customer_Logins WHERE AccountID=1 AND LockedUntil>SYSUTCDATETIME()) THROW 51999,'Lockout failed',1;
INSERT @Results VALUES('Five failed attempts temporarily lock the customer login');
SELECT @Version=Version FROM Customer_Logins WHERE AccountID=1;
EXEC Customer_SaveLogin @Actor=1,@AccountID=1,@Username='customer',@Version=@Version;
BEGIN TRY EXEC Customer_Session 1,@Stamp;THROW 51999,'Old session accepted',1;END TRY BEGIN CATCH IF ERROR_NUMBER()<>51911 THROW;END CATCH;
INSERT @Results VALUES('Admin credential change invalidates existing sessions');
SELECT @Stamp=SecurityStamp FROM Customer_Logins WHERE AccountID=1;
EXEC Customer_SaveGrant @Actor=1,@AccountID=1,@CategoryID=1,@RoleID=1,@Children=1;
EXEC Customer_SaveGrant @Actor=1,@AccountID=1,@CategoryID=3,@RoleID=1,@Children=0;
IF (SELECT COUNT(*) FROM Customer_Guide_Effective(1,1) WHERE Can_View_Document=1)<>2 OR (SELECT COUNT(*) FROM Customer_Guide_Effective(1,2) WHERE Can_View_Document=1)<>1 THROW 51999,'Multi-brand/inheritance failed',1;
IF EXISTS(SELECT 1 FROM Customer_Guide_Effective(2,1) WHERE Can_View_Document=1) THROW 51999,'Other customer gained access',1;
INSERT @Results VALUES('Multi-brand grants, inheritance, other-customer isolation');
EXEC Customer_SaveGrant @Actor=1,@AccountID=1,@CategoryID=2,@RoleID=2,@Children=0;
IF EXISTS(SELECT 1 FROM Customer_Guide_Effective(1,1) WHERE ID=2 AND Can_Download_Document=1) THROW 51999,'Nearest grant failed',1;
BEGIN TRY EXEC Customer_LogDocument 1,@Stamp,1,'download';THROW 51999,'View-only download allowed',1;END TRY BEGIN CATCH IF ERROR_NUMBER()<>51910 THROW;END CATCH;
BEGIN TRY EXEC Customer_LogDocument 1,@Stamp,2,'download';THROW 51999,'Document restriction ignored',1;END TRY BEGIN CATCH IF ERROR_NUMBER()<>51910 THROW;END CATCH;
BEGIN TRY EXEC Customer_LogDocument 1,@Stamp,-1,'view';THROW 51999,'Forged document allowed',1;END TRY BEGIN CATCH IF ERROR_NUMBER()<>51910 THROW;END CATCH;
INSERT @Results VALUES('Nearest role wins; document/download checks deny unauthorized files');
UPDATE Customer_Guide_Grants SET End_Date=DATEADD(day,-1,GETDATE()) WHERE Category_ID=3;
IF EXISTS(SELECT 1 FROM Customer_Guide_Effective(1,2) WHERE Can_View_Document=1) THROW 51999,'Expired grant accepted',1;
UPDATE Customer_Guide_Grants SET End_Date=NULL WHERE Category_ID=3;
UPDATE Brands SET IsActive=0 WHERE ID=2;
IF EXISTS(SELECT 1 FROM Customer_Guide_Effective(1,2)) THROW 51999,'Inactive brand accepted',1;
UPDATE Brands SET IsActive=1 WHERE ID=2;
INSERT @Results VALUES('Expired grants and inactive brands denied immediately');
UPDATE CRM_Accounts SET Is_Active=0 WHERE ID=1;
BEGIN TRY EXEC Customer_Session 1,@Stamp;THROW 51999,'Disabled customer session allowed',1;END TRY BEGIN CATCH IF ERROR_NUMBER()<>51911 THROW;END CATCH;
UPDATE CRM_Accounts SET Is_Active=1 WHERE ID=1;
INSERT @Results VALUES('CRM deactivation blocks existing customer session');
DECLARE @Operation uniqueidentifier=NEWID(),@FeedbackID int;
DECLARE @Submitted TABLE(ID int,Replay bit);
INSERT @Submitted EXEC Customer_SubmitFeedback 1,@Stamp,@Operation,1,1,1,1,'0790000000',N'Test complaint',N'Test details',N'<files/>';
SELECT @FeedbackID=ID FROM @Submitted;
IF NOT EXISTS(SELECT 1 FROM Employee_Feedback_Requests WHERE ID=@FeedbackID AND EmployeeID IS NULL AND SourceType=2 AND ApplicantName=N'عميل الاختبار') THROW 51999,'Customer snapshot failed',1;
IF NOT EXISTS(SELECT 1 FROM Employee_Feedback_Workflow WHERE Request_ID=@FeedbackID AND ReceiverID=1) OR NOT EXISTS(SELECT 1 FROM Employee_Feedback_Notifications WHERE Request_ID=@FeedbackID AND UserID=1) THROW 51999,'Admin routing/notification failed',1;
INSERT @Results VALUES('Complaint keeps CRM snapshot, no fake employee, admin workflow and notification');
DELETE @Submitted;
INSERT @Submitted EXEC Customer_SubmitFeedback 1,@Stamp,@Operation,1,1,1,1,'0790000000',N'Test complaint',N'Test details',N'<files/>';
IF NOT EXISTS(SELECT 1 FROM @Submitted WHERE ID=@FeedbackID AND Replay=1) OR (SELECT COUNT(*) FROM Customer_Portal_Feedback WHERE OperationID=@Operation)<>1 THROW 51999,'Duplicate submission failed',1;
INSERT @Results VALUES('Duplicate form submission returns the original request');
DECLARE @Public TABLE(ID int);
INSERT @Public EXEC Insert_Customer_Feedback_Request @Type=1,@Topic=1,@Brand=1,@Branch=1,@Name=N'Public customer',@Mobile='0790000000',@Title=N'Public intake',@Details=N'Existing API contract',@Disclose=1,@Files=N'<files/>';
IF (SELECT COUNT(*) FROM @Public)<>1 THROW 51999,'Public intake contract broken',1;
INSERT @Results VALUES('Existing public customer intake result contract retained');
SELECT * FROM @Results;
